function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  const validated: ListSessionsMessage = {type: 'list_sessions'};

  const {limit} = message;
  if (limit !== undefined && (typeof limit !== 'number' || !Number.isInteger(limit) || limit < 0 || limit > 200)) {
    return {valid: false, error: 'list_sessions limit must be an integer between 0 and 200'};
  }
  if (typeof limit === 'number') {
    validated.limit = limit;
  }

